// Additive research adapter. The production 0.87 flow remains unchanged.
import{explorerResults as baseline,evidence087,activityLinks087,explorerCareerQuestions as previousQuestions}from'./open-explorer-087.js';
import{inventory088}from'./evidence-088-data.js';import{scoreOnetInterest,profileCorrelation}from'./onet-assessment.js';
export const explorerCareerQuestions=id=>inventory088.find(o=>o.id===id)?.questions||previousQuestions(id);
export function explorerResults(s){const base=baseline(s),p=scoreOnetInterest(s),valid=p.complete&&!p.flat&&!p.nearFlat,added=inventory088.map(o=>({id:o.id,o,fields:o.fields,degree:false,r:valid?profileCorrelation(p.raw,o.vector):null,specific:evidence087(s,o),activityTopics:[...activityLinks087(s,o),...base.rows.filter(r=>({ 'geological-technician':['degree-19204200'],'forest-technician':['degree-19103200'],'environmental-technician':['environmental-science'],'recreation-worker':['degree-27202200']}[o.id]||[]).includes(r.id)&&r.specific.evidence.some(e=>e.domain==='domain'||e.questionId?.endsWith('-044-1'))).map(r=>'subject:'+r.id)]}));return{...base,rows:[...base.rows.filter(r=>r.specific.supported),...added.filter(r=>r.specific.supported),...base.rows.filter(r=>!r.specific.supported),...added.filter(r=>!r.specific.supported)],version:'0.88-research'};}
